struct Cart { lines: Vec<Line>, busy: bool }              // supply half: sole owner

fn render_cart(cart: &Cart, ui: &mut Ui) {                // presentational half: borrows
    for line in &cart.lines {
        ui.row(|ui| {
            ui.label(&line.sku);
            ui.button("remove", Message::Remove(line.sku.clone()));
        });
    }
}
// events return as messages; the owner applies them and the next frame renders again
